Algoritmo Average
  Definir mark Como Entero;
  Definir sum Como Entero <- 0;
  Definir amount Como Entero <- 0;
  Leer mark;
  Mientras mark <> -1 Hacer
    sum <- sum + mark;
    amount <- amount + 1;
    Leer mark;
  FinMientras
  Si amount = 0 Entonces
    Escribir "No marks";
  Sino
    Escribir sum / amount;
  FinSi
FinAlgoritmo
